fn int_to_str(n: Int) -> Str {
    if n < 10 {
        if n == 0 {
            return str_of("0")
        }
        return str_of(char(n + 48))
    } else {
        let mut digits = vec()
        let mut nn = n
        while nn >= 10 {
            digits.push(char((nn % 10) + 48))
            nn = nn / 10
        }
        digits.push(char(nn + 48))
        let mut s = str_of("")
        for d in digits.iter().rev() {
            s = concat(s, str_of(d))
        }
        return s
    }
}

