    if s.chars().nth(0) == Some(char(45)) {
        s = &s && s.chars().skip(1)
        n = n - 1
    }
    for c in s.chars() {
        if c >= char(48) && c <= char(57) {
            n = n * 10 + (c - char(48))
        } else {
            return None
        }
    }
    return Some(n)
}

